// Dump SuperscalarHash programs generated by the reference library for keys "sshcmp-<i>" (i = 0..n-1)
#include "superscalar.hpp"
#include "superscalar_program.hpp"
#include "blake2_generator.hpp"
#include "common.hpp"
#include <cstdio>
#include <cstdlib>
#include <cstring>
static const char* names[] = {"ISUB_R","IXOR_R","IADD_RS","IMUL_R","IROR_C","IADD_C7","IXOR_C7","IADD_C8","IXOR_C8","IADD_C9","IXOR_C9","IMULH_R","ISMULH_R","IMUL_RCP"};
int main(int argc, char** argv) {
	int n = argc > 1 ? atoi(argv[1]) : 100;
	for (int k = 0; k < n; ++k) {
		char key[64]; int len = snprintf(key, sizeof key, "sshcmp-%d", k);
		randomx::Blake2Generator gen(key, len);
		for (int p = 0; p < RANDOMX_CACHE_ACCESSES; ++p) {
			randomx::SuperscalarProgram prog;
			randomx::generateSuperscalar(prog, gen);
			printf("K%d P%d addr=%d size=%u\n", k, p, prog.getAddressRegister(), prog.getSize());
			for (unsigned i = 0; i < prog.getSize(); ++i) {
				randomx::Instruction& in = prog(i);
				printf("%s %u %u %u %u\n", names[in.opcode], in.dst, in.src, in.mod, in.getImm32());
			}
		}
	}
	return 0;
}
